// Gerçek MKV başlıkları. Üretim: ffmpeg 9.0.2-full_build (gyan.dev), 29 Ekim 2026, uydurma bayt yok.
// Kaynak: 1 sn, 64x64 testsrc (libx264 ultrafast yuv420p) + 440 Hz sine; ses codec'i dosya adında.
//   ffmpeg -f lavfi -i testsrc=size=64x64:rate=10:duration=1 -f lavfi -i sine=frequency=440:duration=1 //          -c:v libx264 -pix_fmt yuv420p -preset ultrafast -c:a <aac|libopus|ac3|eac3|dca -strict -2> -shortest x.mkv
//   multi_*: iki sine girişi, -map 0:v -map 1:a -map 2:a, dil etiketleri (multi_aac_aac: tur,eng; multi_ac3_aac: eng,tur)
//   h264_aac_srt: ek -i s.srt -c:s srt (altyazı izi)
// "head" olanlar dosyanın ilk 4096 baytıdır (gerçek bir dosyanın ilk okuma penceresi; Segment boyutu dosyadan büyüktür),
// h264_aac tam dosyadır (12926 bayt). ffprobe ile doğrulanmış iz listesi her adın yanında.
// Bu dosya betikle üretilir (base64); elle düzenleme.
export const MKV_FIXTURES = {
  h264_aac: "",
  h264_opus: "",
  h264_ac3: "",
  h264_eac3: "",
  h264_dts: "",
  multi_aac_aac: "",
  multi_ac3_aac: "",
  h264_aac_srt: "",
} as const;

export type MkvFixtureName = keyof typeof MKV_FIXTURES;

/** Fixture'ı bayt dizisine çevirir (atob tarayıcıda ve Node 16+'da var). */
export function mkvBytes(name: MkvFixtureName): Uint8Array {
  return Uint8Array.from(atob(MKV_FIXTURES[name]), (c) => c.charCodeAt(0));
}
